def strings(language):
    """The strings for a language, falling back to English for anything missing."""
    en, lang = STRINGS["en"], STRINGS.get(language, STRINGS["en"])
    return {k: {**en[k], **lang.get(k, {})} if isinstance(en[k], dict) else lang.get(k, en[k]) for k in en}
